from datetime import datetime, timedelta, date

WEEKDAY_MAP = {"MO": 0, "TU": 1, "WE": 2, "TH": 3, "FR": 4, "SA": 5, "SU": 6}
_MONTH_DAYS = (31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31)


def _is_leap(year: int) -> bool:
    return year % 4 == 0 and (year % 100 != 0 or year % 400 == 0)


def _days_in_month(year: int, month: int) -> int:
    if month == 2 and _is_leap(year):
        return 29
    return _MONTH_DAYS[month - 1]


def _parse_dt(s: str) -> datetime:
    # Accepts "YYYY-MM-DDTHH:MM" and also ignores a trailing "Z".
    return datetime(
        int(s[0:4]),
        int(s[5:7]),
        int(s[8:10]),
        int(s[11:13]),
        int(s[14:16]),
    )


def _format_utc(dt: datetime) -> str:
    return f"{dt.year:04d}-{dt.month:02d}-{dt.day:02d}T{dt.hour:02d}:{dt.minute:02d}Z"


def _lower_bound_date(local_start: datetime, start_dt: datetime) -> date:
    if local_start <= start_dt:
        return start_dt.date()

    d = local_start.date()
    if datetime.combine(d, start_dt.time()) < local_start:
        d += timedelta(days=1)
    return d


def _nth_weekday_date(year: int, month: int, n: int, weekday: int):
    if n == 0:
        return None

    dim = _days_in_month(year, month)

    if n > 0:
        first_wd = date(year, month, 1).weekday()
        day = 1 + (weekday - first_wd) % 7 + 7 * (n - 1)
        if 1 <= day <= dim:
            return date(year, month, day)
        return None

    # n < 0: -1 is last, -2 is second-to-last, etc.
    last_wd = date(year, month, dim).weekday()
    last_occ_day = dim - (last_wd - weekday) % 7
    day = last_occ_day + 7 * (n + 1)
    if 1 <= day <= dim:
        return date(year, month, day)
    return None


def _month_dates(
    year: int,
    month: int,
    start_day: int,
    by_month_day,
    by_nth_weekday,
):
    if by_nth_weekday is not None:
        n, wd = by_nth_weekday
        d = _nth_weekday_date(year, month, n, wd)
        return [d] if d is not None else []

    dim = _days_in_month(year, month)
    days = set()

    if by_month_day is None:
        if start_day <= dim:
            days.add(start_day)
    else:
        for md in by_month_day:
            if md > 0:
                if md <= dim:
                    days.add(md)
            elif md < 0:
                day = dim + md + 1
                if day >= 1:
                    days.add(day)
            # md == 0 is not valid per spec; ignore defensively.

    return [date(year, month, d) for d in sorted(days)]


def _iter_occurrences(
    start_dt: datetime,
    freq: str,
    interval: int,
    lower_date: date,
    upper_dt: datetime,
    until_dt,
    by_weekday,
    by_month_day,
    by_nth_weekday,
):
    start_date = start_dt.date()
    start_time = start_dt.time()

    if freq == "daily":
        limit_days = (upper_dt.date() - start_date).days
        if until_dt is not None:
            limit_days = min(limit_days, (until_dt.date() - start_date).days)

        delta = (lower_date - start_date).days
        if delta <= 0:
            k = 0
        else:
            k = (delta + interval - 1) // interval

        max_k = limit_days // interval
        if k > max_k:
            return

        offset = k * interval
        while True:
            candidate = start_date + timedelta(days=offset)
            dt = datetime.combine(candidate, start_time)

            if dt >= upper_dt:
                break
            if until_dt is not None and dt > until_dt:
                break

            yield dt

            k += 1
            if k > max_k:
                break
            offset += interval

    elif freq == "weekly":
        if not by_weekday:
            return

        allowed = sorted(set(by_weekday))
        start_monday = start_date - timedelta(days=start_date.weekday())

        if lower_date < start_date:
            lower_date = start_date

        orig_week_idx = (lower_date - start_monday).days // 7
        week_idx = orig_week_idx

        rem = week_idx % interval
        if rem:
            week_idx += interval - rem

        if week_idx == orig_week_idx:
            min_wd = lower_date.weekday()
        else:
            min_wd = 0

        candidates = [wd for wd in allowed if wd >= min_wd]
        if not candidates:
            week_idx += interval
            candidates = allowed

        limit_days = (upper_dt.date() - start_monday).days
        if until_dt is not None:
            limit_days = min(limit_days, (until_dt.date() - start_monday).days)

        max_week_idx = limit_days // 7

        while True:
            if week_idx > max_week_idx:
                break

            week_start = start_monday + timedelta(days=week_idx * 7)

            for wd in candidates:
                d = week_start + timedelta(days=wd)
                dt = datetime.combine(d, start_time)

                if dt >= upper_dt:
                    return
                if until_dt is not None and dt > until_dt:
                    return

                yield dt

            week_idx += interval
            candidates = allowed

    elif freq == "monthly":
        start_midx = start_date.year * 12 + start_date.month - 1

        if lower_date < start_date:
            lower_date = start_date

        lower_midx = lower_date.year * 12 + lower_date.month - 1
        midx = max(start_midx, lower_midx)

        rem = (midx - start_midx) % interval
        if rem:
            midx += interval - rem

        stop_midx = upper_dt.year * 12 + upper_dt.month - 1
        if until_dt is not None:
            stop_midx = min(stop_midx, until_dt.year * 12 + until_dt.month - 1)

        while midx <= stop_midx:
            year = midx // 12
            month = midx % 12 + 1

            # Datetime supports years 1..9999; problem data is far inside this,
            # but guard anyway against pathological huge intervals.
            if year < 1 or year > 9999:
                break

            dates = _month_dates(year, month, start_date.day, by_month_day, by_nth_weekday)

            for d in dates:
                if d < lower_date:
                    continue

                dt = datetime.combine(d, start_time)

                if dt >= upper_dt:
                    return
                if until_dt is not None and dt > until_dt:
                    return

                yield dt

            midx += interval

    elif freq == "yearly":
        start_year = start_date.year

        if lower_date < start_date:
            lower_date = start_date

        lower_year = lower_date.year
        delta = lower_year - start_year
        if delta <= 0:
            k = 0
        else:
            k = (delta + interval - 1) // interval

        stop_year = upper_dt.year
        if until_dt is not None:
            stop_year = min(stop_year, until_dt.year)

        if stop_year < start_year:
            return

        max_k = (stop_year - start_year) // interval
        if k > max_k:
            return

        month = start_date.month
        day = start_date.day

        while True:
            year = start_year + k * interval
            if year > stop_year:
                break

            if day <= _days_in_month(year, month):
                d = date(year, month, day)
                if d >= lower_date:
                    dt = datetime.combine(d, start_time)

                    if dt >= upper_dt:
                        break
                    if until_dt is not None and dt > until_dt:
                        break

                    yield dt

            k += 1
            if k > max_k:
                break

    else:
        return


def expand(rule: dict, window_start: str, window_end: str) -> list[str]:
    freq = rule.get("freq")
    if freq not in {"daily", "weekly", "monthly", "yearly"}:
        raise ValueError("unknown freq")

    interval = int(rule.get("interval", 1))
    if interval < 1:
        raise ValueError("interval must be >= 1")

    if "count" in rule and "until" in rule:
        raise ValueError("cannot specify both count and until")

    if "by_month_day" in rule and "by_nth_weekday" in rule:
        raise ValueError("cannot specify both by_month_day and by_nth_weekday")

    start_dt = _parse_dt(rule["start"])
    offset = int(rule.get("utc_offset_minutes", 0))

    count = None
    if "count" in rule:
        count = int(rule["count"])
        if count <= 0:
            return []

    until_dt = None
    if "until" in rule:
        until_dt = _parse_dt(rule["until"])

    exclude = set()
    for ex in rule.get("exclude", []) or []:
        exclude.add(_parse_dt(ex))

    utc_start = _parse_dt(window_start)
    utc_end = _parse_dt(window_end)

    local_start = utc_start + timedelta(minutes=offset)
    local_end = utc_end + timedelta(minutes=offset)

    if local_start >= local_end:
        return []

    if local_end <= start_dt:
        return []

    if until_dt is not None:
        if until_dt < start_dt:
            return []
        if local_start > until_dt:
            return []

    by_weekday = None
    by_month_day = None
    by_nth_weekday = None

    if freq == "weekly":
        if "by_weekday" in rule:
            try:
                by_weekday = [WEEKDAY_MAP[x.upper()] for x in rule["by_weekday"]]
            except KeyError as exc:
                raise ValueError("invalid weekday") from exc
        else:
            by_weekday = [start_dt.weekday()]

    elif freq == "monthly":
        if "by_nth_weekday" in rule:
            n, wd = rule["by_nth_weekday"]
            try:
                wd_idx = WEEKDAY_MAP[wd.upper()]
            except KeyError as exc:
                raise ValueError("invalid weekday") from exc
            by_nth_weekday = (int(n), wd_idx)
        elif "by_month_day" in rule:
            by_month_day = list(rule["by_month_day"])
        else:
            by_month_day = [start_dt.day]

    if count is None:
        lower_date = _lower_bound_date(local_start, start_dt)
        result = []

        for occ in _iter_occurrences(
            start_dt,
            freq,
            interval,
            lower_date,
            local_end,
            until_dt,
            by_weekday,
            by_month_day,
            by_nth_weekday,
        ):
            if occ in exclude:
                continue
            if local_start <= occ < local_end:
                result.append(_format_utc(occ - timedelta(minutes=offset)))

        return result

    # Count rules may be replayed from the start; count is small (<= 2000).
    result = []
    seen = 0
    lower_date = start_dt.date()

    for occ in _iter_occurrences(
        start_dt,
        freq,
        interval,
        lower_date,
        local_end,
        until_dt,
        by_weekday,
        by_month_day,
        by_nth_weekday,
    ):
        seen += 1

        if occ not in exclude and local_start <= occ < local_end:
            result.append(_format_utc(occ - timedelta(minutes=offset)))

        if seen >= count:
            break

    return result
